SELECT /*LGSETC00070.retrieveLabelList*/ label_type_code , NVL(language_code,'KO') AS language_code , label_id , label_name , use_column_name FROM LGCOM_SCREEN_LABEL_M WHERE 1 = 1
AND label_type_code = #{labelTypeCode}
AND language_code = #{languageCode}
AND (UPPER(label_id) LIKE '%' || UPPER(#{labelId}) || '%')
AND (UPPER(label_name) LIKE '%' || UPPER(#{labelName}) || '%')
ORDER BY label_id, language_code

mapper.update:
/*LGSETC00070.updateLabelList*/
	UPDATE LGCOM_SCREEN_LABEL_M
	   SET label_type_code     	  = #{labelTypeCode}	   
	     , label_name   		  = #{labelName}
	     , use_column_name 		  = #{useColumnName}
	     , last_updated_by    	  = #{sessionUserId}
	     , last_update_date    	  = SYSDATE
	 WHERE label_id = #{labelId}
	   AND language_code = #{languageCode}

/*LGSETC00070.deleteLabelList*/
	DELETE FROM LGCOM_SCREEN_LABEL_M
	 WHERE label_id = #{labelId}
	   AND language_code = #{languageCode}

