SELECT /*LGSETC00070.retrieveLabelIdChk*/
 	   COUNT(*) AS cnt
  FROM LGCOM_SCREEN_LABEL_M
 WHERE 1 = 1
   AND label_id = #{labelId}
   AND language_code = #{languageCode}
   AND label_type_code = #{labelTypeCode}
